rep('if("BarcodeDetector" in window){stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"environment"}});v.srcObject=stream;$("#camp").hidden=false;document.body.classList.add("camon");await v.play();const bd=new BarcodeDetector();timer=setInterval(async()=>{try{const r=await bd.detect(v);if(r[0])onCode(r[0].rawValue)}catch(e){}},350)}',
 'if("BarcodeDetector" in window){stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:"environment"},width:{ideal:1920},height:{ideal:1080}}});try{const tr=stream.getVideoTracks()[0],cp=tr.getCapabilities?tr.getCapabilities():{};if(cp.focusMode&&cp.focusMode.includes("continuous"))await tr.applyConstraints({advanced:[{focusMode:"continuous"}]})}catch(e){}v.srcObject=stream;$("#camp").hidden=false;document.body.classList.add("camon");await v.play();const bd=new BarcodeDetector();let busy=false;timer=setInterval(async()=>{if(busy||!v.videoWidth)return;busy=true;try{const r=await bd.detect(v);const hit=r.find(x=>CODE_RE.test(String(x.rawValue).trim()))||r[0];if(hit)onCode(hit.rawValue)}catch(e){}busy=false},250)}')
